<?php
namespace Semizzy\Addons\Education\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\SoftDeletes;
final class EducationAcademicUnit extends Model { use SoftDeletes; protected $table='education_academic_units'; protected $guarded=[]; protected $casts=['active'=>'boolean','metadata'=>'array','verified_at'=>'datetime']; public function institution(){return $this->belongsTo(EducationInstitution::class);} public function parent(){return $this->belongsTo(self::class,'parent_unit_id');} public function children(){return $this->hasMany(self::class,'parent_unit_id');} public function departments(){return $this->hasMany(EducationDepartment::class,'academic_unit_id');} public function programmes(){return $this->hasMany(EducationProgramme::class,'academic_unit_id');}}
